choose.when:
AND EXISTS (
    SELECT 1
    FROM platform_principal_role role_relation
    WHERE role_relation.principal_id = principal.id
      AND role_relation.role_id = #{roleId}
)

choose.otherwise:
AND NOT EXISTS (
    SELECT 1
    FROM platform_principal_role role_relation
    WHERE role_relation.principal_id = principal.id
      AND role_relation.role_id = #{roleId}
)

mapper.select:
SELECT 


ORDER BY account.id DESC
LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE iam_account
SET status = #{status}
WHERE id = #{accountId} AND deleted = 0

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM iam_account_principal relation
    INNER JOIN iam_account account ON account.id = relation.account_id AND account.deleted = 0
    WHERE relation.principal_id = #{principalId} AND relation.account_id <> #{accountId}
)
